SELECT f.form_id::TEXT AS row_id, f.title, f.type_cd, tc.name AS type_name, f.start_dt, f.end_dt, f.login_yn, f.multi_yn, f.use_yn, (SELECT COUNT(*) FROM form_answer a WHERE a.form_id = f.form_id AND a.use_yn = 'Y')::TEXT AS answer_cnt FROM form f LEFT JOIN code tc ON tc.code_id = f.type_cd AND tc.p_code_id = 'FORM00' WHERE f.use_yn = 'Y' AND f.type_cd = #{typeCd}
AND f.title LIKE '%' || #{filterKeyword} || '%'
ORDER BY f.form_id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM form WHERE use_yn = 'Y'
AND type_cd = #{typeCd}
AND title LIKE '%' || #{filterKeyword} || '%'
